import pelatihanOrderQueries from "@tepian-k3/queries/pelatihan/order.queries";
import enrollmentQueries from "@tepian-k3/queries/pelatihan/enrollment.queries";
import pelatihanSchema from "@tepian-k3/schema/pelatihan/pelatihan.schema";
import { TRPCError } from "@trpc/server";
import { z } from "zod";
import { Effect } from "effect";
import {
  approvePelatihanOrderSchema,
  rejectPelatihanOrderApprovalSchema,
  rejectPelatihanPaymentSchema,
} from "@tepian-k3/schema/pelatihan/order.schema";
import {
  createTRPCRouter,
  withPermission,
  protectedProcedure,
  formDataInput,
  formDataProcedure,
} from "../..";
import { runEffect } from "../../utils/run-effect";
import { processAndUploadFile } from "../../utils/image-upload";
import { storageService } from "@tepian-k3/services/storage";

/**
 * Router untuk manajemen order & transaksi pelatihan.
 * - User endpoints: riwayat transaksi, detail, upload bukti bayar
 * - Admin endpoints: semua order, verifikasi pembayaran, kelola enrollment
 */
export const pelatihanOrderRouter = createTRPCRouter({
  // ========== USER ENDPOINTS ==========

  /**
   * Membuat order baru dari keranjang pelatihan user yang sedang login.
   */
  createPelatihanOrder: protectedProcedure.mutation(async ({ ctx }) => {
    return await runEffect(
      pelatihanOrderQueries.createPelatihanOrder(ctx.user.id),
    );
  }),

  /**
   * Mengambil riwayat transaksi pelatihan milik user yang sedang login.
   */
  getUserOrders: protectedProcedure.query(async ({ ctx }) => {
    return await runEffect(pelatihanOrderQueries.getUserOrders(ctx.user.id));
  }),

  /**
   * Mengambil riwayat transaksi pelatihan milik user yang sedang login dengan paginasi.
   */
  getUserOrdersPaginated: protectedProcedure
    .input(
      z.object({
        page: z.number().int().positive().default(1),
        limit: z.number().int().positive().max(100).default(10),
      }),
    )
    .query(async ({ ctx, input }) => {
      return await runEffect(
        pelatihanOrderQueries.getUserOrdersPaginated(ctx.user.id, input),
      );
    }),


  /**
   * Mengambil detail satu transaksi pelatihan berdasarkan ID.
   */
  getUserOrderById: protectedProcedure
    .input(z.object({ id: z.string().uuid() }))
    .query(async ({ ctx, input }) => {
      const order = await runEffect(
        pelatihanOrderQueries.getUserOrderById(input.id, ctx.user.id),
      );

      if (!order) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "Transaksi tidak ditemukan",
        });
      }

      return order;
    }),

  /**
   * User mengupload bukti pembayaran untuk order pelatihan.
   */
  uploadPaymentProof: protectedProcedure
    .input(formDataInput)
    .use(
      formDataProcedure(
        z.object({
          orderId: z.string().uuid(),
          file: z.custom<File>((val) => val instanceof File, {
            message: "File bukti pembayaran wajib diunggah",
          }),
        }),
      ),
    )
    .mutation(async ({ ctx }) => {
      return await runEffect(
        Effect.gen(function* () {
          const { orderId, file } = ctx.input.data;

          const uploadedFile = yield* processAndUploadFile(file, {
            folder: "pelatihan/payment-proofs",
            allowedMimeTypes: ["image/jpeg", "image/png", "application/pdf"],
            maxSize: 5 * 1024 * 1024, // 5MB
          });

          const publicUrl = storageService.getPublicUrl(uploadedFile.key);

          return yield* pelatihanOrderQueries.uploadPaymentProof(
            orderId,
            ctx.user.id,
            publicUrl,
          );
        }),
      );
    }),

  // ========== ADMIN ENDPOINTS ==========

  /**
   * Admin: Mengambil semua order pelatihan dengan paginasi dan filter status.
   */
  getAllOrders: withPermission("pelatihan.view")
    .input(
      z.object({
        page: z.number().int().positive().default(1),
        perPage: z.number().int().positive().max(100).default(20),
        status: z.string().optional(),
      }),
    )
    .query(async ({ input }) => {
      return await runEffect(pelatihanOrderQueries.getAllOrders(input));
    }),

  /**
   * Admin: Menyetujui order pelatihan berbayar.
   */
  approveOrder: withPermission("pelatihan.update")
    .input(approvePelatihanOrderSchema)
    .mutation(async ({ ctx, input }) => {
      return await runEffect(
        pelatihanOrderQueries.approvePelatihanOrder(input.orderId, ctx.user.id),
      );
    }),

  /**
   * Admin: Menolak persetujuan order pelatihan.
   */
  rejectOrderApproval: withPermission("pelatihan.update")
    .input(rejectPelatihanOrderApprovalSchema)
    .mutation(async ({ ctx, input }) => {
      return await runEffect(
        pelatihanOrderQueries.rejectPelatihanOrderApproval(
          input.orderId,
          ctx.user.id,
          input.reason,
        ),
      );
    }),

  /**
   * Admin: Menolak verifikasi pembayaran order pelatihan.
   */
  rejectPayment: withPermission("pelatihan.update")
    .input(rejectPelatihanPaymentSchema)
    .mutation(async ({ ctx, input }) => {
      return await runEffect(
        pelatihanOrderQueries.rejectPelatihanPayment(
          input.orderId,
          ctx.user.id,
          input.reason,
        ),
      );
    }),

  /**
   * Admin: Memverifikasi pembayaran dan otomatis enroll user ke pelatihan.
   */
  verifyPayment: withPermission("pelatihan.update")
    .input(z.object({ orderId: z.string().uuid() }))
    .mutation(async ({ ctx, input }) => {
      return await runEffect(
        pelatihanOrderQueries.verifyPayment(input.orderId, ctx.user.id),
      );
    }),

  /**
   * Admin: Mengambil detail satu order pelatihan beserta info pembayaran dan peserta.
   */
  getAdminOrderById: withPermission("pelatihan.view")
    .input(z.object({ id: z.string().uuid() }))
    .query(async ({ input }) => {
      const result = await runEffect(
        pelatihanOrderQueries.getAdminOrderById(input.id),
      );
      if (!result) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "Order pelatihan tidak ditemukan",
        });
      }
      return result;
    }),

  /**
   * Admin: Mengambil semua enrollment pelatihan dengan paginasi dan filter.
   */
  getAllEnrollments: withPermission("pelatihan.view")
    .input(pelatihanSchema.getAllEnrollmentsSchema)
    .query(async ({ input }) => {
      return await runEffect(enrollmentQueries.getAllEnrollments(input));
    }),

  /**
   * Admin: Mengambil detail enrollment berdasarkan ID.
   */
  getEnrollmentById: withPermission("pelatihan.view")
    .input(z.object({ id: z.string().uuid() }))
    .query(async ({ input }) => {
      const result = await runEffect(
        enrollmentQueries.getEnrollmentById(input.id),
      );
      if (!result) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "Enrollment tidak ditemukan",
        });
      }
      return result;
    }),

  /**
   * Admin: Memperbarui status enrollment peserta.
   */
  updateEnrollmentStatus: withPermission("pelatihan.update")
    .input(
      z.object({
        id: z.string().uuid(),
        status: z.enum([
          "enrolled",
          "in_progress",
          "completed",
          "failed",
          "expired",
        ]),
      }),
    )
    .mutation(async ({ input }) => {
      return await runEffect(
        enrollmentQueries.updateEnrollmentStatus(input.id, input.status),
      );
    }),
});

